cd "$PWD" && python -c "
from databricks.sdk import WorkspaceClient
import inspect
from databricks.sdk.service import jobs, compute
w = WorkspaceClient()
# cleanup pending versions + model
full='workspace.mlpab5b087a.ftmodel698f06'
try:
    for v in w.model_versions.list(full):
        try: w.model_versions.delete(full, v.version)
        except Exception as e: print('delv',v.version,repr(e)[:80])
    w.registered_models.delete(full); print('model deleted')
except Exception as e: print('cleanup', repr(e)[:120])
print('--- JobEnvironment ---', inspect.signature(jobs.JobEnvironment.__init__))
print('--- compute.Environment ---')
try: print(inspect.signature(compute.Environment.__init__))
except Exception as e: print('no compute.Environment', e)
print('--- Task env_key field present? ---', 'environment_key' in jobs.Task.__init__.__code__.co_varnames if hasattr(jobs.Task,'__init__') else 'n/a')
" 2>&1 | tail -20

